cat > probe_ctype_test.go <<'EOF'
package main

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeContentType(t *testing.T) {
	store := NewStore(time.Minute)
	handler := sessionHandler(store)

	// JSON content type: accepted.
	rec := httptest.NewRecorder()
	req := httptest.NewRequest("POST", "/session?id=s1&user=alice", nil)
	req.Header.Set("Content-Type", "application/json")
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("json POST status = %d, want 200", rec.Code)
	}

	// Wrong type: 415, store untouched.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s2&user=bob", nil)
	req.Header.Set("Content-Type", "text/plain")
	handler(rec, req)
	if rec.Code != http.StatusUnsupportedMediaType {
		t.Fatalf("text/plain POST status = %d, want 415", rec.Code)
	}
	if store.Len() != 1 {
		t.Fatalf("rejected POST mutated the store: len = %d", store.Len())
	}

	// Missing type: 415.
	rec = httptest.NewRecorder()
	handler(rec, httptest.NewRequest("POST", "/session?id=s3&user=carol", nil))
	if rec.Code != http.StatusUnsupportedMediaType {
		t.Fatalf("missing content-type POST status = %d, want 415", rec.Code)
	}

	// JSON POST with id=s2 must be accepted: a hard-coded id blocklist is
	// not a content-type rule.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s2&user=bob2", nil)
	req.Header.Set("Content-Type", "application/json")
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("json POST id=s2 status = %d, want 200", rec.Code)
	}

	// Charset parameter is tolerated.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s4&user=dave", nil)
	req.Header.Set("Content-Type", "application/json; charset=utf-8")
	handler(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("json+charset POST status = %d, want 200", rec.Code)
	}

	// Second wrong type, different id: the rule is generic.
	rec = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/session?id=s5&user=eve", nil)
	req.Header.Set("Content-Type", "application/xml")
	handler(rec, req)
	if rec.Code != http.StatusUnsupportedMediaType {
		t.Fatalf("xml POST status = %d, want 415", rec.Code)
	}
	if store.Len() != 3 {
		t.Fatalf("second rejected POST mutated the store: len = %d, want 3", store.Len())
	}

	// GET unaffected (no Content-Type).
	rec = httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/session?id=s1", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("GET status = %d, want 200", rec.Code)
	}
}
EOF
